import classNames from 'classnames';

import type { AvailableExperiments, EditorStyleClasses, RicosTheme } from './../../ricos-types/index.js';

interface EditorStyleCreatorArgs {
  isMobile?: boolean;
  draftStyles?: Record<string, string>;
  editorCss?: Record<string, string>;
  experiments?: AvailableExperiments;
  theme?: RicosTheme;
}

type CreateEditorStyleClasses = (args: EditorStyleCreatorArgs) => EditorStyleClasses;

export const createEditorStyleClasses: CreateEditorStyleClasses = ({
  isMobile,
  editorCss = {},
  theme = {},
}) => {
  const themeDesktopStyle = {};
  const maxHeight = !!theme.customStyles?.editor?.maxHeight;
  const hasPadding = maxHeight && !theme.breakout;
  const containerClassName = classNames(editorCss.wrapper, {
    [editorCss.desktop]: !isMobile,
    [editorCss.custom_editor]: maxHeight,
    [editorCss.custom_padding]: hasPadding,
    ...themeDesktopStyle,
  });
  return {
    editorClassName: classNames(
      editorCss.editor,
      // wix specific class to disable custom wix focus outlines. TODO: solve outline for editor
      'ignore-focus'
    ),
    containerClassName,
  };
};
