import { Version } from './../../../ricos-content/index.js';
import type { RichContent } from './../../../ricos-schema/legacy/wix/rich_content/v1/index.js';
import type { BICallbacks } from './../../../ricos-types/index.js';
import { getContentSummary } from './../../../wix-rich-content-common/lib/ricos-content-analytics.js';

export const publishBI = async (
  content: Promise<RichContent>,
  onPublish: BICallbacks['onPublish'],
  postId?: string
) => {
  const richContent = await content;
  const { pluginsCount, pluginsDetails } = getContentSummary(richContent) || {};
  onPublish?.(
    postId,
    pluginsCount,
    pluginsDetails,
    Version.currentVersion,
    richContent?.metadata?.id
  );
};
