import React, { useEffect } from 'react';

import { ConvertersContext } from './../../pm-converters/context.js';
import type { RicosEditorProps } from './../../ricos-common/index.js';
import { ContentQueryProvider } from './../../ricos-content-query/index.js';
import {
  EditorContextProvider,
  EditorQueryContextProvider,
  PluginExportsContextProvider,
  PluginsContextProvider,
  PluginsEventsContextProvider,
  RicosContextProvider,
  SchemaContextProvider,
  ShortcutsContextProvider,
  ToolbarContextProvider,
  UploadContextProvider,
  ZIndexContextProvider,
  useDevService,
  useTrackRender,
} from './../../ricos-context/index.js';
import { OrchestratorContext } from './../../ricos-context/orchestrator-context.js';
import { PmContentContextProvider } from './../../ricos-context/pm-content-context.js';
import { SelectionContextProvider } from './../../ricos-context/selection-context.js';
import { useShortcuts } from './../shortcuts/use-shortcuts.js';
import type { ModalService } from './../../ricos-modals/index.js';
import { ModalRenderer } from './../../ricos-modals/index.js';
import {
  ModalProvider,
  useModalService,
  useModalStateContext,
} from './../../ricos-modals/modal-service-provider.js';
import { RicosOrchestrator } from './../../ricos-orchestrator/index.js';
import { PluginGlobalComponents } from './../../ricos-plugins/plugin-global-components.js';
import { PluginProviders } from './../../ricos-plugins/plugin-providers.js';
import type { RichContent } from './../../ricos-schema/legacy/wix/rich_content/v1/index.js';
import type { RicosStyles } from './../../ricos-styles/index.js';
import { StylesContextProvider } from './../../ricos-styles/index.js';
import { ThemeProvider, useTheme } from './../../ricos-styles/theme-provider.js';
import type {
  ContentChangeMeta,
  DebugMode,
  Helpers,
  INotifier,
  LegacyEditorPluginConfig,
  Platform,
  RicosPortal as RicosPortalType,
  TFunction,
  EditorPluginCreator,
  EditorPluginOptions,
} from './../../ricos-types/index.js';
import { BiContextProvider } from './../../_shared/bi-context-provider/bi-context-provider.js';
import { BiHelpersProvider } from './../../_shared/bi-helpers-context/bi-helpers-context.js';
import { EditorBaseUrlContextProvider } from './../../_shared/editor-base-url/editor-base-url-context.js';
import {
  RequestServiceProvider,
  useRequestService,
} from './../../_shared/request-service-provider/request-service-provider.js';
import {
  WixInstanceContextProvider,
  useWixInstanceService,
} from './../../_shared/request-service-provider/wix-instance-context.js';
import { RicosIconThemeProvider } from './../../_shared/ricos-icon-theme-provider.js';
import { SitePagesFetchContextProvider } from './../../_shared/site-pages/site-pages-fetch-context.js';
import { SomeEditorPropsContextProvider } from './../../_shared/some-editor-props-context.js';
import { useUserInteraction } from './../../_shared/use-user-interaction.js';
import type { JSONContent } from './../../tiptap/core/index.js';
import { getLangDir } from './../../wix-rich-content-common/index.js';
import { EditorEventsFallbackProvider } from './../../editor-common/editor-events-context.js';
import { RicosPortal } from './../../editor-common/index.js';
import { MobileToolbar } from './../../toolbars-v3/index.js';
import { ToolbarBoundaryProvider } from './../../toolbars-v3/toolbar-boundary.js';

import { resolvePlugins } from '../../_shared/dynamic-plugins-map.js';
import { normalizeContent } from '../normalize-content.js';
import type { RicosEditorRef } from '../ricos-editor-ref.js';
import { hasActiveUploads } from './active-uploads.js';
import { ErrorNotifier } from './error-notifier.js';
import { RicosEditorWithForwardRef as RicosEditor } from './ricos-editor.js';
import { RicosErrorBoundary } from './ricos-error-boundary.js';
import { RicosToolbars } from './ricos-toolbars.js';
import { StyledEditorContainer } from './styled-editor-container.js';

type Props = RicosEditorProps & {
  platform: Platform;
  t: TFunction;
  debugMode?: DebugMode[];
  jsdomMode?: boolean;
  pluginConfig?: LegacyEditorPluginConfig;
  helpers?: Helpers;
  biLogger?: { logV2: (params: any) => void };
  pluginsMap: Partial<Record<string, EditorPluginCreator>>;
};

type OuterProps = Omit<Props, 'pluginsMap'> & {
  pluginsMap?: Partial<Record<string, EditorPluginCreator>>;
  pluginTypes?: EditorPluginOptions['type'][];
};

// This is a local hack for injected content and placeholder reactivity. We kill all other props except of these two
const InjectedContentContext = React.createContext<RichContent | undefined>(undefined);
const PlaceholderContext = React.createContext<string | undefined>(undefined);

const RicosEditorFallback = ({ Editor }: $TSFixMe) => <Editor />;

// Needed to have access to context in useShortcuts
const ShortcutsSetup = () => {
  useShortcuts();
  return null;
};

const InnerFullRicosEditor = React.forwardRef<RicosEditorRef, Props>((props, ref) => {
  const modalService = useModalService();
  const theme = useTheme();
  const devService = useDevService();
  const wixInstance = useWixInstanceService();
  const makeRequestService = useRequestService();

  const [orchestrator] = React.useState<RicosOrchestrator>(
    () =>
      new RicosOrchestrator({
        editorProps: props,
        t: props.t,
        platform: props.platform,
        modalService: modalService as ModalService,
        devService,
        wixInstance,
        makeRequestService,
        pluginsMap: props.pluginsMap,
      })
  );

  useModalStateContext({
    onSelectorContextValue: selectorContextValue => {
      return (orchestrator.modalStateSelectorContextValue = selectorContextValue);
    },
  });

  const [portalRef, setPortalRef] = React.useState<RicosPortalType | null>(null);
  const editorRef = React.useRef<HTMLDivElement>(null);
  const [errorNotifierRef, setErrorNotifierRef] = React.useState<INotifier | null>(null);
  const [inputRef, setInputRef] = React.useState<HTMLInputElement | null>(null);

  useTrackRender('FullRicosEditor');

  const { lastInteraction } = useUserInteraction();

  React.useEffect(() => {
    //@ts-ignore
    window.ricosEditor = orchestrator.getServices().editor;

    return () => {
      //@ts-ignore
      // oxlint-disable-next-line fp/no-delete
      delete window.ricosEditor;
    };
  }, []);

  React.useEffect(() => {
    if (errorNotifierRef && inputRef) {
      orchestrator.setUpdateServiceDom(
        () => errorNotifierRef,
        () => inputRef
      );
    }
  }, [orchestrator, errorNotifierRef, inputRef]);

  const Editor = React.useMemo(
    () =>
      React.memo(() => {
        const injectedContent = React.useContext(InjectedContentContext);
        const placeholder = React.useContext(PlaceholderContext);
        const [isBusy, setIsBusy] = React.useState(false);
        const onBusyChange = React.useCallback(
          (pmContent: JSONContent) => {
            const { onBusyChange } = props;
            const isCurrentlyBusy = hasActiveUploads(pmContent);
            if (isBusy !== isCurrentlyBusy) {
              setIsBusy(isCurrentlyBusy);
              onBusyChange?.(isCurrentlyBusy);
            }
          },
          [props.onBusyChange, isBusy]
        );

        const onChange = React.useCallback(
          (content: RichContent, meta: ContentChangeMeta) => {
            props.onChange?.(content, meta);
          },
          [props.onChange]
        );

        return (
          <RicosEditor
            {...props}
            injectedContent={injectedContent}
            placeholder={placeholder}
            onChange={onChange}
            onInternalBusyChange={onBusyChange}
            ref={ref}
          />
        );
      }),
    []
  );

  const Children = props.children || RicosEditorFallback;

  const {
    plugins,
    shortcuts,
    content,
    uploadService,
    updateService,
    editor,
    styles,
    pluginsEvents,
    schema,
    zIndexService,
    getEditorQuery,
    context,
    converters,
  } = orchestrator.getServices();
  const pluginExports = orchestrator.getPluginExports();

  const documentStyle = (schema.getContent().documentStyle as RichContent['documentStyle']) || {};

  const languageDir = getLangDir(context.locale);

  useEffect(() => {
    if (portalRef) {
      orchestrator.setPortalRef(portalRef);
    }
  }, [portalRef]);

  // Keep the orchestrator's BI helpers ref in sync with the latest helpers from props.
  // Set synchronously during render (not in useEffect) so that any event handlers
  // or subscriptions that fire during this render cycle see the latest helpers.
  orchestrator.biHelpersRef.current = props.helpers || {};

  return (
    <OrchestratorContext.Provider value={orchestrator}>
      <RicosErrorBoundary onError={props.onError} editor={editor}>
        <BiContextProvider biLogger={props.biLogger}>
          <BiHelpersProvider helpers={props.helpers || {}}>
            <EditorBaseUrlContextProvider baseUrl={props.baseUrl}>
              <SitePagesFetchContextProvider>
                <ConvertersContext.Provider value={converters}>
                  <ToolbarBoundaryProvider
                    editorContainer={editorRef.current}
                    externalContainer={props.container}
                  >
                    <StylesContextProvider
                      styles={styles as RicosStyles}
                      documentStyle={documentStyle}
                      theme={theme}
                      environment={props.environment ?? 'liveSite'}
                      isMobile={context.isMobile}
                    >
                      <StyledEditorContainer ref={editorRef}>
                        <ZIndexContextProvider zIndexService={zIndexService}>
                          <PluginsContextProvider plugins={plugins}>
                            <PluginProviders plugins={plugins}>
                              <RicosPortal
                                languageDir={languageDir}
                                ref={setPortalRef}
                                environment={props.environment}
                              />
                              {portalRef && (
                                <RicosContextProvider
                                  t={context.t}
                                  isMobile={context.isMobile}
                                  experiments={context.experiments}
                                  locale={context.locale}
                                  localeContent={context.localeContent}
                                  languageDir={context.languageDir}
                                  theme={theme}
                                  portal={portalRef}
                                  debugMode={context.debugMode}
                                  jsdomMode={context.jsdomMode}
                                  platform={context.platform}
                                  content={content}
                                  environment={context.environment}
                                  tabIndex={context.tabIndex}
                                  lastInteraction={lastInteraction}
                                  tabFocusBehavior={context.tabFocusBehavior}
                                  colorManager={props.colorManager}
                                >
                                  <>
                                    <EditorContextProvider editor={editor}>
                                      <EditorQueryContextProvider editorQuery={getEditorQuery()}>
                                        <ShortcutsContextProvider shortcuts={shortcuts}>
                                          <>
                                            <PluginsEventsContextProvider
                                              pluginsEvents={pluginsEvents}
                                            >
                                              <PluginExportsContextProvider value={pluginExports}>
                                                <SchemaContextProvider schema={schema}>
                                                  <UploadContextProvider
                                                    uploadService={uploadService}
                                                    updateService={updateService}
                                                  >
                                                    <ToolbarContextProvider
                                                      toolbarSettings={props.toolbarSettings}
                                                      onSelectorContextValue={selectorContextValue =>
                                                        (orchestrator.toolbarStateSelectorContextValue =
                                                          selectorContextValue)
                                                      }
                                                    >
                                                      <ContentQueryProvider
                                                        editor={editor.adapter.tiptapEditor}
                                                      >
                                                        <SelectionContextProvider
                                                          onSelectorContextValue={selectorContextValue =>
                                                            (orchestrator.selectionSelectorContextValue =
                                                              selectorContextValue)
                                                          }
                                                        >
                                                          <PmContentContextProvider
                                                            onSelectorContextValue={selectorContextValue =>
                                                              (orchestrator.pmContentSelectorContextValue =
                                                                selectorContextValue)
                                                            }
                                                          >
                                                            <MobileToolbar />
                                                            <InjectedContentContext.Provider
                                                              value={props.injectedContent}
                                                            >
                                                              <PlaceholderContext.Provider
                                                                value={props.placeholder}
                                                              >
                                                                <Children Editor={Editor} />
                                                                <PluginGlobalComponents
                                                                  plugins={plugins}
                                                                />
                                                              </PlaceholderContext.Provider>
                                                            </InjectedContentContext.Provider>
                                                            <RicosToolbars />
                                                          </PmContentContextProvider>
                                                        </SelectionContextProvider>
                                                        <ModalRenderer />
                                                      </ContentQueryProvider>
                                                    </ToolbarContextProvider>
                                                  </UploadContextProvider>
                                                </SchemaContextProvider>
                                              </PluginExportsContextProvider>
                                            </PluginsEventsContextProvider>
                                            <ShortcutsSetup />
                                          </>
                                        </ShortcutsContextProvider>
                                      </EditorQueryContextProvider>
                                    </EditorContextProvider>
                                    <ErrorNotifier
                                      ref={setErrorNotifierRef}
                                      languageDir={languageDir}
                                    />
                                    <input
                                      ref={setInputRef}
                                      id={'ricos-file-upload-input'}
                                      key="ricosUploadInput"
                                      type="file"
                                      style={{ display: 'none' }}
                                      tabIndex={-1}
                                      multiple
                                    />
                                  </>
                                </RicosContextProvider>
                              )}
                            </PluginProviders>
                          </PluginsContextProvider>
                        </ZIndexContextProvider>
                      </StyledEditorContainer>
                    </StylesContextProvider>
                  </ToolbarBoundaryProvider>
                </ConvertersContext.Provider>
              </SitePagesFetchContextProvider>
            </EditorBaseUrlContextProvider>
          </BiHelpersProvider>
        </BiContextProvider>
      </RicosErrorBoundary>
    </OrchestratorContext.Provider>
  );
});

const isPlainObject = (x: unknown): boolean =>
  x !== null && typeof x === 'object' && Object.getPrototypeOf(x) === Object.prototype;

export const FullRicosEditor = React.forwardRef<RicosEditorRef, OuterProps>(
  ({ content, injectedContent, pluginTypes, pluginsMap: pluginsMapProp, ...restProps }, ref) => {
    if (!(isPlainObject(content) || content === null || content === undefined)) {
      console.error('Invalid content prop provided to RicosEditor:', content);
      restProps.onError?.('Invalid content prop provided to RicosEditor');
      throw Error('Invalid content prop provided to RicosEdidtor');
    }
    if (
      !(isPlainObject(injectedContent) || injectedContent === null || injectedContent === undefined)
    ) {
      console.error('Invalid injectedContent prop provided to RicosEditor:', injectedContent);
      restProps.onError?.('Invalid injectedContent prop provided to RicosEditor');
      throw Error('Invalid injectedContent prop provided to RicosEditor');
    }
    const normalizedContent = React.useMemo(
      () => (content ? normalizeContent(content) : content),
      [content]
    );
    const normalizedInjectedContent = React.useMemo(
      () => (injectedContent ? normalizeContent(injectedContent) : injectedContent),
      [injectedContent]
    );

    // Resolve dynamic plugins if pluginsMap wasn't provided directly (override/bundle path)
    const [resolvedPluginsMap, setResolvedPluginsMap] = React.useState<Partial<
      Record<string, EditorPluginCreator>
    > | null>(pluginsMapProp ?? null);

    React.useEffect(() => {
      if (pluginsMapProp) {
        return;
      }
      let cancelled = false;
      resolvePlugins(pluginTypes ?? []).then(map => {
        if (!cancelled) {
          setResolvedPluginsMap(map);
        }
      });
      return () => {
        cancelled = true;
      };
    }, [pluginTypes, pluginsMapProp]);

    if (!resolvedPluginsMap) {
      return <>{restProps.loadingPlaceholder || <div />}</>;
    }

    return (
      <EditorEventsFallbackProvider>
        <RicosIconThemeProvider environment={restProps.environment}>
          <ModalProvider modalSettings={restProps.modalSettings}>
            <ThemeProvider theme={restProps.theme}>
              <SomeEditorPropsContextProvider
                visitorUploads={restProps.visitorUploads}
                fileUploadSizeLimit={restProps.fileUploadSizeLimit}
                biSettings={restProps.biSettings}
                pickMedia={restProps.pickMedia}
                generalLinkSettings={restProps.generalLinkSettings}
                historySettings={restProps.historySettings}
                helpers={restProps.helpers}
                iframeSandboxDomain={restProps.iframeSandboxDomain}
                instance={restProps.instance}
              >
                <RequestServiceProvider
                  wixClient={restProps.wixClient}
                  instance={restProps.instance}
                >
                  <WixInstanceContextProvider instance={restProps.instance}>
                    <InnerFullRicosEditor
                      {...restProps}
                      pluginsMap={resolvedPluginsMap}
                      content={normalizedContent}
                      injectedContent={normalizedInjectedContent}
                      ref={ref}
                    />
                  </WixInstanceContextProvider>
                </RequestServiceProvider>
              </SomeEditorPropsContextProvider>
            </ThemeProvider>
          </ModalProvider>
        </RicosIconThemeProvider>
      </EditorEventsFallbackProvider>
    );
  }
);

// oxlint-disable-next-line import/no-default-export
export default FullRicosEditor;
