import {
  TIPTAP_CARD_CONTENT_TYPE,
  TIPTAP_CARD_FOOTER_TYPE,
  TIPTAP_CARD_HEADER_TYPE,
  TIPTAP_TABLE_HEADER_CELL_TYPE,
} from './../../ricos-content/consts.js';
import { Node_Type } from './../../ricos-types/plugin-types.js';
import { isCellSelection } from './../../_shared/is-cell-selection.js';
import { findParentNodeClosestToPos } from './../../tiptap/index.js';
import type { Editor } from './../../tiptap/core/index.js';
import type { Node as ProsemirrorNode, ResolvedPos } from './../../tiptap/pm/model.js';
import { NodeSelection, type Selection } from './../../tiptap/pm/state.js';
import { TableMap } from './../../plugin-table/tiptap/tablemap.js';

type SelectionRange = {
  from: number;
  to: number;
  type?: 'node' | 'text' | 'all';
};

interface SelectionContext {
  selection: Selection;
  doc: ProsemirrorNode;
  $from: ResolvedPos;
  from: number;
  to: number;
}

/**
 * Resolves incremental selection expansion in steps:
 * 1. Check if selection spans beyond current node or if current node is empty
 * 2. If current node is not fully selected, select it
 * 3. While node is fully selected, move up to the parent node
 * 4. Apply node-specific selection handling (if applicable)
 * 5. Select parent node content
 * 6. Fallback to document selection
 *
 * @param editor - TipTap editor instance
 * @returns Selection range or null if already at maximum selection
 */
export const resolveIncrementalSelection = (editor: Editor): SelectionRange | null => {
  const { state } = editor;
  const { selection, doc } = state;
  const { from, to } = selection;
  const $from: ResolvedPos = doc.resolve(from);

  const context: SelectionContext = {
    selection,
    doc,
    $from,
    from,
    to,
  };

  // Check if document is already fully selected
  if (from === 0 && to === doc.content.size) {
    return null;
  }

  // Special case: a NodeSelection on a SMART_BLOCK_CELL escalates to a
  // NodeSelection on the parent SMART_BLOCK. Handled before the depth/text
  // logic below, which would otherwise expand the cell selection into a plain
  // text selection of the block's content. Mirrors the `selectSmartBlock`
  // command (plugin-smart-block/tiptap/smart-block-extension.ts).
  if (
    selection instanceof NodeSelection &&
    selection.node.type.name === Node_Type.SMART_BLOCK_CELL
  ) {
    const smartBlock = findParentNodeClosestToPos(
      $from,
      node => node.type.name === Node_Type.SMART_BLOCK
    );
    if (smartBlock) {
      return { from: smartBlock.pos, to: smartBlock.pos + smartBlock.node.nodeSize, type: 'node' };
    }
  }

  const initialDepth = $from.depth;
  const currentNodeStart = $from.start(initialDepth);
  const currentNodeEnd = $from.end(initialDepth);

  // 1. Early exit: check if selection spans beyond current node or node is empty
  const selectionSpansBeyondCurrentNode = from < currentNodeStart || to > currentNodeEnd;
  const nodeIsEmpty = $from.node(initialDepth).isText && !$from.node(initialDepth).text;

  if (selectionSpansBeyondCurrentNode || nodeIsEmpty) {
    return selectAll(context);
  }

  // 2. Select current node content if not fully selected
  // For card nodes, also accept "selection covers all inner text cursors"
  // as fully-selected — tiptap's `setTextSelection` clamps `to` down to the
  // last valid textblock position (`atEnd`), which is strictly less than
  // the CARD's content end. Without this, advancing past a CARD that sits
  // at the doc edge gets stuck on (cardStart, atEnd) repeatedly.
  // For CARD_HEADER / CARD_CONTENT / CARD_FOOTER wrappers, skip this step
  // entirely so the expansion lands on CARD content rather than wrapper
  // content (the wrappers are structural and not meaningful selections on
  // their own).
  const isCurrentNodeCard = $from.node(initialDepth).type.name === Node_Type.CARD;
  const isCurrentNodeFullySelected = isCurrentNodeCard
    ? isCardFullySelected(from, to, $from, initialDepth)
    : from === currentNodeStart && to === currentNodeEnd;
  const isCurrentNodeCardWrapper = isCardWrapper($from.node(initialDepth));

  if (!isCurrentNodeFullySelected && !isCurrentNodeCardWrapper) {
    return { from: currentNodeStart, to: currentNodeEnd, type: 'text' };
  }

  // 3. Find the parent-most selected context (handles SKIP_TO_PARENT_NODES logic)
  const currentContext = findParentMostSelectedContext(context);
  const currentDepth = currentContext.$from.depth;
  const currentNode = currentContext.$from.node(currentDepth);

  // 4. Apply node-specific selection handling (lists, tables, etc.)
  const nodeType = currentNode.type.name as Node_Type;
  switch (nodeType) {
    // List-related nodes all use the same logic to find outermost list
    case Node_Type.LIST_ITEM:
    case Node_Type.COLLAPSIBLE_ITEM:
    case Node_Type.BULLETED_LIST:
    case Node_Type.CHECKBOX_LIST:
    case Node_Type.ORDERED_LIST:
    case Node_Type.COLLAPSIBLE_LIST:
    case Node_Type.COLLAPSIBLE_ITEM_TITLE:
    case Node_Type.COLLAPSIBLE_ITEM_BODY: {
      const selection = handleListNodeSelection(currentContext);
      if (selection) {
        return selection;
      }
      break;
    }

    // Table-related nodes use table selection logic
    case Node_Type.TABLE_CELL:
    case TIPTAP_TABLE_HEADER_CELL_TYPE as Node_Type: {
      const selection = handleTableCellSelection(currentContext);
      if (selection) {
        return selection;
      }
      break;
    }

    // Smart block cell: select all smart block content
    case Node_Type.SMART_BLOCK_CELL: {
      const selection = handleSmartBlockCellSelection(currentContext);
      if (selection) {
        return selection;
      }
      break;
    }

    // Layout-related nodes use layout selection logic
    case Node_Type.LAYOUT:
    case Node_Type.LAYOUT_CELL: {
      const selection = handleLayoutSelection(currentContext);
      if (selection) {
        return selection;
      }
      break;
    }

    default:
      break;
  }

  // 5. Select parent node (if exists)
  if (currentDepth > 0) {
    return selectParentNode(currentContext);
  }

  // 6. Fallback to document selection
  return selectAll(context);
};

// Constants for boundary calculations
const PARENT_TAG_OFFSET = 1;

/**
 * A CARD is "fully selected" if either:
 *   - the selection matches the CARD's content boundaries exactly (within
 *     PARENT_TAG_OFFSET tolerance), or
 *   - the selection covers every inner-text cursor position inside the
 *     CARD. `setTextSelection` clamps to `atStart`/`atEnd` of the doc, so
 *     a CARD at the doc edge ends up with `to` strictly less than its
 *     content end — without this fallback the next incremental press gets
 *     stuck on the same clamped range.
 */
const isCardFullySelected = (
  from: number,
  to: number,
  $from: ResolvedPos,
  depth: number
): boolean => {
  const cardStart = $from.start(depth);
  const cardEnd = $from.end(depth);

  if (from - cardStart <= PARENT_TAG_OFFSET && cardEnd - to <= PARENT_TAG_OFFSET) {
    return true;
  }

  const card = $from.node(depth);
  let firstInnerCursor: number | null = null;
  let lastInnerCursor: number | null = null;
  card.descendants((node, offset) => {
    if (node.isTextblock) {
      const innerStart = cardStart + offset + 1;
      const innerEnd = cardStart + offset + node.nodeSize - 1;
      if (firstInnerCursor === null) {
        firstInnerCursor = innerStart;
      }
      lastInnerCursor = innerEnd;
    }
    return true;
  });

  return (
    firstInnerCursor !== null &&
    lastInnerCursor !== null &&
    from <= firstInnerCursor &&
    to >= lastInnerCursor
  );
};

/**
 * Nodes that bypass their own selection boundary and jump to parent level.
 * This enables faster selection (e.g., "select entire list in 2 clicks").
 */
const SKIP_TO_PARENT_NODES = [
  Node_Type.LIST_ITEM, // Skip to select parent list
  Node_Type.COLLAPSIBLE_ITEM_BODY, // Skip to select parent collapsible list
  Node_Type.LAYOUT_CELL, // Skip to select parent layout
];

/**
 * Helper for calculating node boundaries including opening/closing tags
 */
const getNodeBoundaries = (pos: number, nodeSize: number) => ({
  from: pos,
  to: pos + nodeSize,
});

/**
 * Helper to check if all cells in a table are selected
 */
const isFullTableCellSelection = (selection: Selection, tableNode: ProsemirrorNode): boolean => {
  if (!isCellSelection(selection)) {
    return false;
  }

  try {
    const tableMap = TableMap.get(tableNode);
    const selectedRect = tableMap.rectBetween(
      selection.$anchorCell.pos - selection.$anchorCell.start(-1),
      selection.$headCell.pos - selection.$headCell.start(-1)
    );

    // Check if the selected rectangle covers the entire table
    return (
      selectedRect.left === 0 &&
      selectedRect.right === tableMap.width &&
      selectedRect.top === 0 &&
      selectedRect.bottom === tableMap.height
    );
  } catch {
    // If there's any error in calculating, assume not fully selected
    return false;
  }
};

/**
 * Returns a selection range that covers the entire document,
 * or the card content if the selection is inside a CARD node.
 */
const selectAll = (context: SelectionContext): SelectionRange => {
  const card = findParentNodeClosestToPos(context.$from, node => node.type.name === Node_Type.CARD);

  if (card) {
    const cardContentStart = card.pos + PARENT_TAG_OFFSET;
    const cardContentEnd = card.pos + card.node.nodeSize - PARENT_TAG_OFFSET;
    // Use boundary tolerance since TextSelection adjusts positions to valid cursor spots
    const isCardContentSelected =
      Math.abs(context.from - cardContentStart) <= PARENT_TAG_OFFSET &&
      Math.abs(context.to - cardContentEnd) <= PARENT_TAG_OFFSET;
    const isSelectionBeyondCard = context.from < cardContentStart || context.to > cardContentEnd;
    // TextSelection at card content boundaries adjusts the start position to the nearest
    // valid cursor spot (deeper in the tree), while the end typically stays at the boundary.
    // Detect this adjusted state so we don't loop between card content and its adjusted form.
    const isCardContentAdjusted =
      context.from > cardContentStart &&
      context.to >= cardContentEnd - PARENT_TAG_OFFSET &&
      context.to <= cardContentEnd;

    if (!isCardContentSelected && !isCardContentAdjusted && !isSelectionBeyondCard) {
      return { from: cardContentStart, to: cardContentEnd, type: 'text' };
    }
  }

  return { from: 0, to: context.doc.content.size, type: 'all' };
};

/**
 * Finds the parent-most node by traversing up the hierarchy while content is effectively selected.
 * Continues traversing up while the current selection encompasses the parent node's content
 * (within a tolerance of 1 position to account for node boundaries).
 *
 * @param context - The current selection context
 * @returns Updated SelectionContext reflecting the highest parent node with selected content
 */
const findParentMostSelectedContext = (context: SelectionContext): SelectionContext => {
  const { $from, from, to, doc } = context;

  let currentDepth = $from.depth;
  let selectionStart = from;
  let selectionEnd = to;

  while (currentDepth > 0) {
    const parentDepth = currentDepth - 1;
    const parentContentStart = $from.start(parentDepth);
    const parentContentEnd = $from.end(parentDepth);

    // Check if parent content is selected (accounting for parent tags)
    const startBoundaryDifference = Math.abs(selectionStart - parentContentStart);
    const endBoundaryDifference = Math.abs(selectionEnd - parentContentEnd);
    const isParentContentSelected =
      startBoundaryDifference <= PARENT_TAG_OFFSET && endBoundaryDifference <= PARENT_TAG_OFFSET;

    // or if parent is a list item
    const parentNode = $from.node(parentDepth);
    const isSkipToParentNode = SKIP_TO_PARENT_NODES.includes(parentNode.type.name as Node_Type);

    // Stop at CARD boundary so selectParentNode handles the card → document transition
    const isCardParent = parentNode.type.name === Node_Type.CARD;
    // Stop at the wrapper boundary (CARD_HEADER / CARD_CONTENT / CARD_FOOTER)
    // so the LAYOUT inside it gets its own selection step. Without this, a
    // tightly-wrapping CARD_HEADER (single LAYOUT child) lets the climb step
    // straight past the LAYOUT into the wrapper, skipping the LAYOUT case.
    const isCardWrapperParent = isCardWrapper(parentNode);

    if ((isParentContentSelected && !isCardParent && !isCardWrapperParent) || isSkipToParentNode) {
      // Move selection scope up to parent level
      currentDepth = parentDepth;
      selectionStart = parentContentStart;
      selectionEnd = parentContentEnd;
    } else {
      // Parent content not selected, stop traversal
      break;
    }
  }

  return {
    ...context,
    $from: doc.resolve(selectionStart),
    from: selectionStart,
    to: selectionEnd,
  };
};

/**
 * Selects the parent node of the current context.
 * Uses appropriate selection type (node vs text) and boundaries.
 *
 * CARD_HEADER, CARD_CONTENT, and CARD_FOOTER are structural wrappers that
 * should never be selected on their own — only their content (text/layout)
 * or the whole CARD is a meaningful selection. Skip past them when computing
 * the parent.
 */
const isCardWrapper = (node: ProsemirrorNode): boolean =>
  node.type.name === TIPTAP_CARD_HEADER_TYPE ||
  node.type.name === TIPTAP_CARD_CONTENT_TYPE ||
  node.type.name === TIPTAP_CARD_FOOTER_TYPE;

const selectParentNode = (context: SelectionContext): SelectionRange => {
  const currentDepth = context.$from.depth;
  let parentDepth = currentDepth - 1;
  let parentNode = context.$from.node(parentDepth);
  while (parentDepth > 0 && isCardWrapper(parentNode)) {
    parentDepth -= 1;
    parentNode = context.$from.node(parentDepth);
  }
  const parentNodeStart = context.$from.start(parentDepth);
  const parentNodeEnd = context.$from.end(parentDepth);

  // Check if parent's content is not fully selected
  if (context.from > parentNodeStart || context.to < parentNodeEnd) {
    const isCardNode = parentNode.type.name === Node_Type.CARD;
    const selectionType = isCardNode ? 'text' : parentNode.isBlock ? 'node' : 'text';

    if (selectionType === 'node' && parentDepth > 0) {
      // Use node boundaries (including tags) for block nodes (not at document level)
      const parentPos = context.$from.before(parentDepth);
      const nodeBoundaries = getNodeBoundaries(parentPos, parentNode.nodeSize);
      return { ...nodeBoundaries, type: 'node' };
    } else {
      // Use content boundaries for text selection or document level
      return { from: parentNodeStart, to: parentNodeEnd, type: 'text' };
    }
  }

  // Parent is already fully selected, select entire document
  return selectAll(context);
};

/**
 * Handles selection for list node types
 * Finds the outermost list containing the current selection
 */
const handleListNodeSelection = (context: SelectionContext): SelectionRange | null => {
  const LIST_TYPES = [
    Node_Type.BULLETED_LIST,
    Node_Type.CHECKBOX_LIST,
    Node_Type.ORDERED_LIST,
    Node_Type.COLLAPSIBLE_LIST,
  ];

  const findOutermostList = (selection: Selection) => {
    let currentList = null;
    let currentDepth = selection.$from.depth;

    while (currentDepth > 0) {
      const node = selection.$from.node(currentDepth);
      if (LIST_TYPES.includes(node.type.name as Node_Type)) {
        currentList = { node, pos: selection.$from.before(currentDepth) };
      }
      currentDepth--;
    }

    return currentList;
  };

  const outermostList = findOutermostList(context.selection);
  if (!outermostList) {
    return selectAll(context);
  }

  const { from: outermostListStart, to: outermostListEnd } = getNodeBoundaries(
    outermostList.pos,
    outermostList.node.nodeSize
  );

  // Calculate content boundaries for comparison
  const listContentStart = outermostList.pos + PARENT_TAG_OFFSET;
  const listContentEnd = outermostList.pos + outermostList.node.nodeSize - PARENT_TAG_OFFSET;

  // If the selection already covers the list content, select all
  if (context.from === listContentStart && context.to === listContentEnd) {
    return selectAll(context);
  }

  return { from: outermostListStart, to: outermostListEnd, type: 'text' };
};

/**
 * Handles selection for table cell node types
 * Finds the table containing the current selection and determines next selection level
 */
const handleTableCellSelection = (context: SelectionContext): SelectionRange | null => {
  const table = findParentNodeClosestToPos(
    context.$from,
    node => node.type.name === Node_Type.TABLE
  );

  if (!table) {
    return selectAll(context);
  }

  // If all table cells are already selected, move to document selection
  if (isFullTableCellSelection(context.selection, table.node)) {
    return selectAll(context);
  }

  // Select the entire table
  const tableBoundaries = getNodeBoundaries(table.pos, table.node.nodeSize);
  return { ...tableBoundaries, type: 'node' };
};

/**
 * Handles selection for layout node types
 * Finds the layout containing the current selection and determines next selection level
 */
const handleLayoutSelection = (context: SelectionContext): SelectionRange | null => {
  const layout = findParentNodeClosestToPos(
    context.$from,
    node => node.type.name === Node_Type.LAYOUT
  );

  if (!layout) {
    return selectAll(context);
  }

  const layoutBoundaries = getNodeBoundaries(layout.pos, layout.node.nodeSize);

  // If layout is already selected, move to document selection
  if (context.from <= layoutBoundaries.from && context.to >= layoutBoundaries.to) {
    return selectAll(context);
  }

  // When the LAYOUT is wrapped in a single-child CARD_HEADER / CARD_FOOTER,
  // there's no text content between the LAYOUT and the wrapper boundary, so
  // a TextSelection at the LAYOUT's outer boundaries gets clamped inward to
  // the first/last textblock position by tiptap's `setTextSelection`. Use a
  // NodeSelection instead, which selects the LAYOUT itself as one unit.
  const $layoutPos = context.doc.resolve(layout.pos);
  const layoutParentName = $layoutPos.parent.type.name;
  const isLayoutInCardWrapper =
    layoutParentName === TIPTAP_CARD_HEADER_TYPE || layoutParentName === TIPTAP_CARD_FOOTER_TYPE;
  if (isLayoutInCardWrapper) {
    return { ...layoutBoundaries, type: 'node' };
  }

  // Select the entire layout
  return { ...layoutBoundaries, type: 'text' };
};

/**
 * Handles selection for smart block cell node types.
 * Expands selection to cover all content within the parent smart block.
 */
const handleSmartBlockCellSelection = (context: SelectionContext): SelectionRange | null => {
  const smartBlock = findParentNodeClosestToPos(
    context.$from,
    node => node.type.name === Node_Type.SMART_BLOCK
  );

  if (!smartBlock) {
    return selectAll(context);
  }

  // Use inner content positions (depth 1, inside smart_block) rather than outer boundaries.
  // Outer boundaries (smartBlock.pos, smartBlock.pos + nodeSize) are at document depth 0
  // (between isolating block nodes), where coordsAtPos returns invalid coordinates for
  // ReactNodeView-based nodes, causing floating-ui to position the toolbar at (0,0) and hide it.
  return {
    from: smartBlock.pos + PARENT_TAG_OFFSET,
    to: smartBlock.pos + smartBlock.node.nodeSize - PARENT_TAG_OFFSET,
    type: 'text',
  };
};
