import { Box, SidePanel, Text } from '@wix/design-system';
import type { FC } from 'react';
import React, { Fragment, useContext, useMemo } from 'react';

import { RicosContext, ShortcutsContext } from './../../ricos-context/index.js';
import { useModalService } from './../../ricos-modals/index.js';
import type { LocalizedDisplayData, ShortcutDataProvider } from './../../ricos-types/index.js';
import { PanelHeader } from './../../ui-components/index.js';

import { ShortcutsSheet } from './shortcuts-sheet.js';

export const SHORTCUT_SHEET_MODAL_ID = 'shortcuts-help';
const SHORTCUT_DIALOG_WIDTH = 380;
const SHORTCUT_DIALOG_MAX_HEIGHT = 600;

export const ShortcutsDialog: FC = () => {
  const modalService = useModalService();
  const ricosContext = useContext(RicosContext);
  const shortcuts = useContext(ShortcutsContext) as ShortcutDataProvider;

  const { t, platform } = ricosContext;
  const handleClose = () => modalService.closeModal(SHORTCUT_SHEET_MODAL_ID);

  const { sortedDisplayData, title } = useMemo(() => {
    const sheet = new ShortcutsSheet(shortcuts, ricosContext);
    const displayData = sheet.getDisplayData();
    const helpShortcutKeys = shortcuts.getShortcutDisplayData(
      'OpenShortcutsSheet',
      t,
      platform
    ).keyCombinationText;

    return {
      sortedDisplayData: displayData,
      title: `${t('ShortcutsSheet_Title')} ${helpShortcutKeys}`,
    };
  }, [shortcuts, t, platform]);

  const renderShortcutKeys = (keys: string[] | string) => {
    if (Array.isArray(keys)) {
      return keys.map((key, index) => (
        <Fragment key={key}>
          <Box gap="6px">{renderShortcutKeys(key)}</Box>
          {index < keys.length - 1 && <span>{t('ShortcutsSheet_Key_Separator')}</span>}
        </Fragment>
      ));
    }

    return keys.split(' ').map(key => (
      <Box
        key={key}
        height={30}
        width={30}
        align="center"
        verticalAlign="middle"
        borderRadius="6px"
        border="1px solid"
        borderColor="D60"
        flexShrink={0}
      >
        <Text size="small" weight="thin" secondary>
          {key}
        </Text>
      </Box>
    ));
  };

  const renderShortcutsGroup = (groupName: string, shortcuts: LocalizedDisplayData[]) => (
    <SidePanel.Section key={groupName} titleVisible={false}>
      <Box padding="SP3" paddingLeft="SP4" paddingRight="SP4">
        <Text weight="bold" size="medium">
          {t(groupName)}
        </Text>
      </Box>
      <Box
        paddingLeft="SP4"
        paddingRight="SP4"
        paddingTop="SP1"
        paddingBottom="SP3"
        gap="SP3"
        direction="vertical"
      >
        {shortcuts.map(shortcut => (
          <SidePanel.Field key={shortcut.name} divider={false} noPadding>
            <Box verticalAlign="middle" align="space-between">
              <Text>{shortcut.description}</Text>
              <Box gap="SP1">{renderShortcutKeys(shortcut.keyCombinationText)}</Box>
            </Box>
          </SidePanel.Field>
        ))}
      </Box>
    </SidePanel.Section>
  );

  return (
    <SidePanel
      closeButtonProps={{
        onClick: handleClose,
      }}
      skin="floating"
      maxHeight={SHORTCUT_DIALOG_MAX_HEIGHT}
      width={SHORTCUT_DIALOG_WIDTH}
      draggable
    >
      <PanelHeader title={title} />
      <SidePanel.Content noPadding>
        <Box direction="vertical" overflow="auto" height="100%">
          {Object.entries(sortedDisplayData).map(([groupName, shortcuts]) =>
            renderShortcutsGroup(groupName, shortcuts)
          )}
        </Box>
      </SidePanel.Content>
    </SidePanel>
  );
};
