import type { EditorPlugin, EditorPluginOptions } from './../../ricos-types/index.js';

export const isEditorPlugin = (
  pluginOrConfig: EditorPlugin | EditorPluginOptions
): pluginOrConfig is EditorPlugin => {
  return 'tiptapExtensions' in pluginOrConfig;
};

export const isEditorPluginOptions = (
  pluginOrConfig: EditorPlugin | EditorPluginOptions
): pluginOrConfig is EditorPluginOptions => {
  return !('tiptapExtensions' in pluginOrConfig);
};

export const isCommonPluginOptions = (
  pluginOrConfig: EditorPlugin | EditorPluginOptions
): pluginOrConfig is Extract<EditorPluginOptions, { type: 'LAYOUT' | 'layout' | 'fontSize' }> => {
  return (
    !('tiptapExtensions' in pluginOrConfig) &&
    ['LAYOUT', 'layout', 'fontSize'].includes(pluginOrConfig.type)
  );
};
