import { generateId, toSizeInKb } from './../ricos-content/index.js';
import type { LayoutData, Node, RichContent } from './../ricos-schema/legacy/wix/rich_content/v1/index.js';
import {
  ButtonData_Type,
  Decoration_Type,
  LayoutData_Banner_Position,
  Node_Type,
} from './../ricos-schema/legacy/wix/rich_content/v1/index.js';

import { getValidColorValue } from '../ricos-content/utils.js';
import { filterUploadingNodes } from './tiptap/active-uploads.js';

const isEmptyText = (node: Node): boolean => node.type === Node_Type.TEXT && !node.textData?.text;

const isEmptyParagraph = (node: Node): boolean =>
  node.type === Node_Type.PARAGRAPH && (node.nodes ?? []).every(isEmptyText);

/**
 * Banner LAYOUTs live only at their container's edge: TOP (and legacy
 * position-less) banners first, BOTTOM banners last. Trailing empty paragraphs
 * after a BOTTOM banner are tolerated — with the card plugin off,
 * tiptap-extensions/trailing-node.ts parks one after a doc-level layout and it
 * is persisted, so a strict last-index rule would demote a legit footer on
 * reload. Mirrors isValidBannerLocation in banner-drop-prevention-plugin.ts:
 * a missing position means TOP.
 */
const isBannerPlacementValid = (
  banner: NonNullable<LayoutData['banner']>,
  index: number,
  siblings: Node[]
): boolean =>
  banner.position === LayoutData_Banner_Position.BOTTOM
    ? siblings.slice(index + 1).every(isEmptyParagraph)
    : index === 0;

const withoutBanner = (layoutData: LayoutData): LayoutData => {
  const { banner, ...rest } = layoutData;
  return rest;
};

// Only two node lists may legitimately hold a banner LAYOUT: the document root
// (no parent) and a CARD's children — the lists plugin-card's converter reads
// its header / footer from.
const isBannerContainer = (parent?: Node): boolean => !parent || parent.type === Node_Type.CARD;

/**
 * Documents authored outside the editor (AI generation, converters, server-side
 * writers) can arrive with `banner` on a LAYOUT that sits in the middle of its
 * container. plugin-card's converter would then hoist that layout into
 * CARD_HEADER / CARD_FOOTER and silently reorder the document, so a misplaced
 * banner loses its banner role here — it stays a plain layout in place.
 */
const normalizeLayoutNode = (node: Node, index: number, siblings: Node[], parent?: Node): Node => {
  const nodes = Array.isArray(node.nodes) ? normalizeNodes(node.nodes, node) : node.nodes;
  const { layoutData } = node;

  if (!layoutData?.banner) {
    return { ...node, nodes };
  }

  return isBannerContainer(parent) && isBannerPlacementValid(layoutData.banner, index, siblings)
    ? { ...node, nodes }
    : { ...node, nodes, layoutData: withoutBanner(layoutData) };
};

// `parent` is the node whose children `nodes` are — omitted for the document root.
const normalizeNodes = (nodes: Node[], parent?: Node): Node[] =>
  nodes
    .filter(node => !isEmptyText(node))
    .map((originalNode, index, siblings) => {
      const node = { ...originalNode, id: originalNode.id || generateId() };

      if (node.type === Node_Type.TABLE_CELL) {
        return normalizeTableCellNode(node);
      }

      if (node.type === Node_Type.FILE) {
        return normalizeFileNode(node);
      }

      if (node.type === Node_Type.BUTTON) {
        return normalizeButtonNode(node);
      }

      if (node.type === Node_Type.IMAGE) {
        return normalizeImageNode(node);
      }

      if (node.type === Node_Type.LAYOUT) {
        return normalizeLayoutNode(node, index, siblings, parent);
      }

      return {
        ...node,
        nodes: Array.isArray(node.nodes) ? normalizeNodes(node.nodes, node) : node.nodes,
      };
    });

const normalizeTableCellNode = (node: Node): Node => {
  return {
    ...node,
    nodes: Array.isArray(node.nodes) ? normalizeNodes(node.nodes, node) : node.nodes,
    tableCellData: node.tableCellData
      ? {
          ...node.tableCellData,
          borderColors: node.tableCellData.borderColors
            ? {
                left: getValidColorValue(node.tableCellData?.borderColors?.left),
                right: getValidColorValue(node.tableCellData?.borderColors?.right),
                top: getValidColorValue(node.tableCellData?.borderColors?.top),
                bottom: getValidColorValue(node.tableCellData?.borderColors?.bottom),
              }
            : node.tableCellData.borderColors,
        }
      : node.tableCellData,
  };
};

const normalizeFileNode = (node: Node): Node => {
  const size = node.fileData?.size;

  if (size === undefined) {
    return node;
  }

  const FILE_MAX_SIZE_IN_BYTES = 2e9; // 2GB

  return {
    ...node,
    fileData: {
      ...node.fileData,
      size: Math.min(size, FILE_MAX_SIZE_IN_BYTES),
      sizeInKb: toSizeInKb(size),
    },
  };
};

const normalizeButtonNode = (node: Node): Node => {
  const borderRadius = node.buttonData?.styles?.border?.radius;
  const borderWidth = node.buttonData?.styles?.border?.width;

  if (borderRadius === undefined && borderWidth === undefined) {
    return node;
  }

  const normalizeBorderValue = (value: number | undefined): number | undefined =>
    value !== undefined ? Math.round(value) : undefined;

  const normalized = {
    ...node,
    buttonData: {
      type: ButtonData_Type.ACTION, // adding button type to resolve TS error
      ...node.buttonData,
      styles: {
        ...node.buttonData?.styles,
        border: {
          radius: normalizeBorderValue(borderRadius),
          width: normalizeBorderValue(borderWidth),
        },
      },
    },
  };
  return normalized;
};

const normalizeImageNode = (node: Node): Node => {
  const caption = node.imageData?.caption;

  if (caption === '') {
    return {
      ...node,
      imageData: {
        ...node.imageData,
        caption: undefined,
      },
    };
  }

  if (!caption || node.nodes?.length) {
    return node;
  }

  const normalized: Node = {
    ...node,
    nodes: [
      {
        type: Node_Type.CAPTION,
        id: generateId(),
        nodes: [
          {
            type: Node_Type.TEXT,
            id: '',
            nodes: [],
            textData: {
              text: caption,
              // Ensures backwards compatibility. Previously it wasn't possible to have a spoiler without a caption.
              decorations: node.imageData?.containerData?.spoiler?.enabled
                ? [{ type: Decoration_Type.SPOILER }]
                : [],
            },
          },
        ],
      },
    ],
  };

  return normalized;
};

export const normalizeContent = (content: RichContent): RichContent => ({
  ...content,
  nodes: normalizeNodes(filterUploadingNodes(content.nodes ?? [])),
});
