import type { KeyboardShortcut } from './../../ricos-types/index.js';
import { createShortcut } from './../../ricos-types/index.js';
import { AllSelection } from './../../tiptap/pm/state.js';

import { resolveIncrementalSelection } from './resolve-incremental-selection.js';
import { ShortcutsDialog } from './shortcuts-dialog.js';

const defaultCommand: KeyboardShortcut['command'] = ({ event }) => {
  event?.preventDefault();
  return 'continue';
};

export const generalShortcuts: KeyboardShortcut[] = [
  createShortcut({
    name: 'OpenShortcutsSheet',
    description: 'ShortcutsSheet_General_OpenKeyboardShortcutsSheet',
    group: 'ShortcutsSheet_Section_General',
    keys: {
      macOs: 'Meta+/',
      windows: 'Ctrl+/',
    },
    enabled: true,
    showInShortcutSheet: false,
    command: ({ modalService, editor }) => {
      modalService.openModal({
        id: 'shortcuts-help',
        Component: ShortcutsDialog,
        componentProps: {},
        dragHandleSelector: '[data-drag-handler]',
        enableDrag: true,
        layout: 'floating',
        positioning: {
          referenceElement: editor.view.dom,
          placement: 'right-start',
        },
      });
      return 'continue';
    },
  }),
  createShortcut({
    name: 'AddHorizontalTabulation',
    description: 'ShortcutsSheet_General_AddHorizontalTabulation',
    group: 'ShortcutsSheet_Section_General',
    keys: {
      macOs: 'Tab',
      windows: 'Tab',
    },
    enabled: false,
    showInShortcutSheet: true,
    command: ({ publicCommands, event }) => {
      const selection = publicCommands.getSelection();

      if (selection.isFocused) {
        event?.preventDefault();
      }

      return 'continue';
    },
  }),
  createShortcut({
    name: 'MoveSelectionThroughElements',
    description: 'ShortcutsSheet_General_MoveSelectionThroughAllElements',
    group: 'ShortcutsSheet_Section_General',
    keys: {
      macOs: 'Arrow',
      windows: 'Arrow',
    },
    enabled: false,
    showInShortcutSheet: true,
    command: defaultCommand,
  }),
  createShortcut({
    name: 'SelectAll',
    description: 'ShortcutsSheet_General_SelectAll',
    group: 'ShortcutsSheet_Section_General',
    keys: {
      macOs: 'Meta+A',
      windows: 'Ctrl+A',
    },
    enabled: true,
    showInShortcutSheet: true,
    command: ({ editor, event }) => {
      event?.preventDefault();
      event?.stopPropagation();

      const nextSelection = resolveIncrementalSelection(editor);

      if (nextSelection) {
        let success: boolean;
        if (nextSelection.type === 'all') {
          const { state, view } = editor;
          view.dispatch(state.tr.setSelection(new AllSelection(state.doc)));
          success = true;
        } else if (nextSelection.type === 'node') {
          success = editor.commands.setNodeSelection(nextSelection.from);
        } else {
          success = editor.commands.setTextSelection(nextSelection);
        }
        return success ? 'handled' : 'continue';
      }

      // nextSelection is null - either we handled the selection internally (e.g., table)
      // or we reached the document boundaries
      return 'handled';
    },
  }),
  createShortcut({
    name: 'SelectTextBlocks',
    description: 'ShortcutsSheet_General_SelectTextBlocks',
    group: 'ShortcutsSheet_Section_General',
    keys: {
      macOs: 'Shift+Arrow',
      windows: 'Shift+Arrow',
    },
    enabled: false,
    showInShortcutSheet: true,
    command: defaultCommand,
  }),
  createShortcut({
    name: 'PasteWithoutFormatting',
    description: 'ShortcutsSheet_Formatting_PasteWithoutFormatting',
    group: 'ShortcutsSheet_Section_Formatting',
    keys: {
      macOs: 'Meta+Shift+V',
      windows: 'Ctrl+Shift+V',
    },
    enabled: false,
    showInShortcutSheet: true,
    command: defaultCommand,
  }),
];

