import classNames from 'classnames';
import React, { forwardRef, useContext } from 'react';

import { StylesContext } from './../../ricos-styles/index.js';

import { EDITOR_ROOT } from '../data-hooks.js';
import s from '../statics/styles/editor-styles-scss.js';

export const StyledEditorContainer = forwardRef<HTMLDivElement, { children: React.ReactNode }>(
  ({ children }, ref) => {
    const { cssVars, setEditorElement, stylePreset } = useContext(StylesContext);

    return (
      //dir="" is for mobile editor's padding (css selector) -- do not remove/modify it
      <div
        dir=""
        ref={el => {
          el && setEditorElement(el);

          if (typeof ref === 'function') {
            ref(el);
          } else if (ref) {
            ref.current = el;
          }
        }}
        data-hook={EDITOR_ROOT}
        className={classNames(s.fullRicosEditor, stylePreset)}
        style={cssVars}
      >
        {children}
      </div>
    );
  }
);
