import { Notification } from '@wix/design-system';
import React, { forwardRef, useCallback, useImperativeHandle, useState } from 'react';

import type { IMessage, INotifier } from './../../ricos-types/index.js';
import { Trans } from './../../wix-rich-content-common/index.js';
import { ErrorMessageMap } from './../../wix-rich-content-common/lib/error-message-map.js';

type ErrorNotifierProps = {
  languageDir?: string;
};

/**
 * Deliberately above the ZIndexService's `NOTIFICATION` layer (5500 desktop / 100500 mobile):
 * upload errors surface while host overlays such as the Media Manager (z-index 10000) are still
 * open, and the notification has to win against those too. Carried over verbatim from the
 * hand-rolled toast this replaces.
 */
const NOTIFICATION_Z_INDEX = 100002;

const MULTIPLE_ERRORS_TRANSLATION_KEY = 'UploadFile_Error_Generic_Toast_Multiple';

/**
 * A single error is reported with its own copy; anything beyond that collapses into one
 * counted message.
 *
 * Note that `MediaUploadErrorKey.GENERIC` is `0` and therefore falsy, so a lone generic error
 * also takes the counted branch. Pinned in `error-notifier.spec.tsx` — fixing it changes
 * user-visible text and belongs in its own change.
 */
const getTranslationKey = (error: IMessage, errorCount: number) =>
  errorCount === 1 && error.key
    ? ErrorMessageMap[error.key as keyof typeof ErrorMessageMap]
    : MULTIPLE_ERRORS_TRANSLATION_KEY;

const getErrorMessage = (error: IMessage, errorCount: number) => {
  const translationKey = getTranslationKey(error, errorCount);
  if (!translationKey) {
    return error.msg;
  }

  const upgradeUrl = error.args?.upgradeUrl as string | undefined;

  return (
    <Trans
      i18nKey={translationKey}
      values={{ ...error.args, errors: errorCount }}
      components={{
        error: error.msg as React.ReactElement,
        ...(upgradeUrl && {
          link: (
            <a href={upgradeUrl} target="_blank" rel="noreferrer">
              {' '}
            </a>
          ),
        }),
      }}
    />
  );
};

export const ErrorNotifier = forwardRef<INotifier, ErrorNotifierProps>(({ languageDir }, ref) => {
  const [error, setError] = useState<IMessage>({});
  const [errorCount, setErrorCount] = useState(0);

  const notify = useCallback((notified: IMessage) => {
    setError(notified);
    setErrorCount(count => count + 1);
  }, []);

  useImperativeHandle(ref, () => ({ notify }), [notify]);

  if (errorCount <= 0) {
    return null;
  }

  return (
    <div style={{ display: 'contents' }} dir={languageDir}>
      <Notification
        dataHook="error-notifier"
        show
        skin="error"
        type="sticky"
        zIndex={NOTIFICATION_Z_INDEX}
        onClose={() => setErrorCount(0)}
      >
        <Notification.TextLabel ellipsis={false}>
          {getErrorMessage(error, errorCount)}
        </Notification.TextLabel>
        <Notification.CloseButton />
      </Notification>
    </div>
  );
});

ErrorNotifier.displayName = 'ErrorNotifier';
