import type { Media, Node } from './../../ricos-schema/legacy/wix/rich_content/v1/index.js';
import { Node_Type } from './../../ricos-types/index.js';
import type {
  PmAudioNode,
  PmFileNode,
  PmGalleryNode,
  PmHtmlNode,
  PmImageNode,
  PmLayoutNode,
  PmVideoNode,
} from './../../_shared/pm-node-types.js';
import type { JSONContent } from './../../tiptap/core/index.js';

const isUploadingAudioRich = (node: Node) =>
  node.type === Node_Type.AUDIO &&
  (!node?.audioData?.audio?.src || node.audioData.audio.src.id?.startsWith?.('blob:'));

const isUploadingAudioPm = (node: JSONContent) => {
  if (node.type === Node_Type.AUDIO) {
    const pmNode = node as PmAudioNode;
    return pmNode.attrs.loading;
  }

  return false;
};

const isUploadingImageRich = (node: Node) =>
  node.type === Node_Type.IMAGE && !node?.imageData?.image?.src;

const isUploadingImagePm = (node: JSONContent) => {
  if (node.type === Node_Type.IMAGE) {
    const pmNode = node as PmImageNode;
    return pmNode.attrs.loading;
  }

  return false;
};

const isUploadingLayoutMediaPm = (node: JSONContent) => {
  if (node.type === Node_Type.LAYOUT) {
    const pmNode = node as PmLayoutNode;
    return pmNode.attrs.loading?.backgroundImage || pmNode.attrs.loading?.backdropImage;
  }

  return false;
};

const isGeneratingAiWidget = (node: JSONContent) => {
  if (node.type === Node_Type.HTML) {
    const pmNode = node as PmHtmlNode;
    return pmNode.attrs.state?.status === 'LOADING';
  }

  return false;
};

const isUploadingVideoRich = (node: Node) =>
  node.type === Node_Type.VIDEO &&
  (!node?.videoData?.video?.src || node.videoData.video.src.url?.startsWith?.('blob:'));

const isUploadingVideoPm = (node: JSONContent) => {
  if (node.type === Node_Type.VIDEO) {
    const pmNode = node as PmVideoNode;
    return pmNode.attrs.loading;
  }

  return false;
};

const isUploadingFileRich = (node: Node) => {
  return node.type === Node_Type.FILE && !node?.fileData?.src;
};

const isUploadingFilePm = (node: JSONContent) => {
  if (node.type === Node_Type.FILE) {
    const pmNode = node as PmFileNode;
    return pmNode.attrs.loading;
  }

  return false;
};

const isUploadedMedia = (media: Media | undefined) => media?.src?.url || media?.src?.id;

const isUploadingGalleryRich = (node: Node) => {
  return (
    node.type === Node_Type.GALLERY &&
    node.galleryData?.items?.some(
      galleryItem =>
        ('image' in galleryItem && !isUploadedMedia(galleryItem.image?.media)) ||
        ('video' in galleryItem && !isUploadedMedia(galleryItem.video?.media))
    )
  );
};

const isUploadingGalleryPm = (node: JSONContent) => {
  if (node.type === Node_Type.GALLERY) {
    const pmNode = node as PmGalleryNode;
    return pmNode.attrs.items.some(item => item.loading);
  }
  return false;
};

const getAllNestedPmNodes = (pmContent: JSONContent) => {
  const nodes: JSONContent[] = [];
  const nodesToVisit = [...(pmContent?.content ?? [])];

  while (nodesToVisit.length) {
    const node = nodesToVisit.pop();
    if (node) {
      nodes.push(node);
    }
    if (node?.content?.length) {
      nodesToVisit.push(...node.content);
    }
  }

  return nodes;
};

export const hasActiveUploads = (pmContent: JSONContent) => {
  const allPmNodes = getAllNestedPmNodes(pmContent);

  return allPmNodes.some(
    node =>
      isUploadingVideoPm(node) ||
      isUploadingAudioPm(node) ||
      isUploadingFilePm(node) ||
      isUploadingGalleryPm(node) ||
      isUploadingImagePm(node) ||
      isUploadingLayoutMediaPm(node) ||
      isGeneratingAiWidget(node)
  );
};

const removeUploadingGalleryItems = (node: Node): Node => ({
  ...node,
  galleryData: {
    ...node.galleryData,
    items:
      node.galleryData?.items?.filter(item =>
        item.image
          ? isUploadedMedia(item.image.media)
          : item.video
            ? isUploadedMedia(item.video.media)
            : item
      ) || [],
  },
});

export const filterUploadingNodes = (nodes: Node[]): Node[] =>
  nodes.map(cleanUpUploadingNode).filter(Boolean) as Node[];

const cleanUpUploadingNode = (node: Node): Node | undefined =>
  isUploadingAudioRich(node) ||
  isUploadingFileRich(node) ||
  isUploadingImageRich(node) ||
  isUploadingVideoRich(node)
    ? undefined
    : isUploadingGalleryRich(node)
      ? removeUploadingGalleryItems(node)
      : node.nodes?.length
        ? {
            ...node,
            nodes: filterUploadingNodes(node.nodes),
          }
        : node;
