import type { ForwardedRef } from 'react';
import React, { forwardRef } from 'react';

import type { RicosEditorProps } from './../../ricos-common/index.js';
import { Version } from './../../ricos-content/index.js';
import { isRichContentEqual } from './../../ricos-content/lib/is-rich-content-equal.js';
import type { GeneralContext } from './../../ricos-context/index.js';
import {
  EditorContextConsumer,
  RicosContextConsumer,
  SchemaContextConsumer,
} from './../../ricos-context/index.js';
import type { RichContent } from './../../ricos-schema/legacy/wix/rich_content/v1/index.js';
import type {
  EditorStyleClasses,
  FocusPosition,
  Helpers,
  HtmlAttributes,
  LegacyEditorPluginConfig,
  OpenModalOptions,
  RicosServices,
} from './../../ricos-types/index.js';
import type { JSONContent } from './../../tiptap/core/index.js';
import { addDevToolsClickListener } from './../../wix-rich-content-common/index.js';
import {
  RicosDevToolsLazy,
  shouldShowDebuggingInfo,
} from './../../wix-rich-content-common/lib/dev-tools.js';
import {
  EditorEvents,
  EditorEventsContext,
} from './../../editor-common/editor-events-context.js';
import type { TiptapAdapter } from './../../tiptap-editor/components/rich-content-adapter.js';
import { editorFocusDescriptionId } from './../../tiptap-editor/components/RicosTiptapEditor/ricos-tiptap-editor.js';
import { RicosTiptapEditor } from './../../tiptap-editor/index.js';

import { invokeAtomicBlockFocus } from '../../_shared/invoke-atomic-block-focus.js';
import { updatePlaceholder } from '../../tiptap-extensions/placeholder.js';
import type { RicosEditorRef } from '../ricos-editor-ref.js';
import editorCss from '../statics/styles/editor-styles-scss.js';
import { publishBI } from '../utils/bi/publish.js';
import { createEditorStyleClasses } from '../utils/create-editor-style-classes.js';

type RicosEditorState = {
  htmlAttributes: HtmlAttributes;
  debugInvokedWithMouse?: boolean;
};

type RicosEditorWithOnBusyChange = RicosEditorProps & {
  onInternalBusyChange: (pmContent: JSONContent) => void;
  pluginConfig?: LegacyEditorPluginConfig;
  helpers?: Helpers;
  biLogger?: { logV2: (params: any) => void };
};

type Props = RicosEditorWithOnBusyChange & {
  ricosContext: GeneralContext;
  editor: RicosServices['editor'];
  schema: RicosServices['schema'];
};

// oxlint-disable-next-line
const PUBLISH_DEPRECATION_WARNING_v9 = `Please provide the postId via RicosEditor biSettings prop and use editorEvents.publish() APIs for publishing.
The getContent(postId, isPublishing) API is deprecated and will be removed in ricos v9.0.0`;

class RicosEditor extends React.Component<Props, RicosEditorState> implements RicosEditorRef {
  state: Readonly<RicosEditorState> = {
    htmlAttributes: {} as HtmlAttributes,
  };

  private readonly editorStyleClasses: EditorStyleClasses;

  private isLastChangeEdit = false;

  private firstEdit = false;

  private tiptapAdapter: TiptapAdapter;

  constructor(props: Props) {
    super(props);
    const { isMobile, experiments, theme, ricosContext } = props;
    this.editorStyleClasses = createEditorStyleClasses({
      isMobile,
      experiments,
      editorCss,
      theme,
    });

    this.tiptapAdapter = props.editor.adapter;

    const editorDomElement = this.tiptapAdapter.tiptapEditor.view.dom;
    editorDomElement.setAttribute('role', 'textbox');
    editorDomElement.setAttribute('aria-multiline', 'true');
    editorDomElement.setAttribute(
      'aria-label',
      this.props.htmlAttributes?.ariaLabel || ricosContext.t('Editor_Main_AriaLabel')
    );
    editorDomElement.setAttribute('aria-describedby', editorFocusDescriptionId);
  }

  componentWillReceiveProps(newProps: Props) {
    if (newProps.injectedContent) {
      if (
        !isRichContentEqual(
          this.props.injectedContent as RichContent,
          newProps.injectedContent as RichContent
        )
      ) {
        const content = newProps.injectedContent;
        // setting timeout to avoid "flushSync was called from inside a lifecycle method" error
        setTimeout(() => {
          this.props.schema?.setContent(content);
        }, 0);
      }
    }

    if (this.props.placeholder !== newProps.placeholder) {
      updatePlaceholder(this.tiptapAdapter.tiptapEditor, newProps.placeholder || '');
    }
  }

  focus: RicosEditorRef['focus'] = (focusPosition?: FocusPosition) => {
    this.tiptapAdapter.focus(focusPosition);
  };

  blur: RicosEditorRef['blur'] = () => {
    this.tiptapAdapter.blur();
  };

  undo: RicosEditorRef['undo'] = () => {
    this.tiptapAdapter.tiptapEditor.chain().focus().undo().run();
  };

  redo: RicosEditorRef['redo'] = () => {
    this.tiptapAdapter.tiptapEditor.chain().focus().redo().run();
  };

  setContent: RicosEditorRef['setContent'] = content => {
    this.props.schema.setContent(content);
  };

  openModal: RicosEditorRef['openModal'] = (options: OpenModalOptions) => {
    this.tiptapAdapter.openModal(options);
  };

  getContent: RicosEditorRef['getContent'] = async (postId, forPublish) => {
    const content = Promise.resolve(this.props.schema.getContent());
    if (postId && forPublish) {
      console.warn(PUBLISH_DEPRECATION_WARNING_v9); // oxlint-disable-line
      const onPublish = this.props.helpers?.onPublish;
      publishBI(content, onPublish, postId);
    }
    return content;
  };

  getContentPromise: RicosEditorRef['getContentPromise'] = ({ publishId } = {}) =>
    this.getContent(publishId, !!publishId);

  getContentTraits: RicosEditorRef['getContentTraits'] = () => {
    return {
      isEmpty: this.props.schema.isEmpty(),
      isContentChanged: this.props.schema.isContentChanged(),
      isLastChangeEdit: this.isLastChangeEdit,
    };
  };

  getToolbarProps: RicosEditorRef['getToolbarProps'] = type =>
    this.tiptapAdapter.getToolbarProps(type);

  useToolbarProps: RicosEditorRef['useToolbarProps'] = type =>
    this.tiptapAdapter.useToolbarProps(type);

  useToolbarWixelProps: RicosEditorRef['useToolbarWixelProps'] = () =>
    this.tiptapAdapter.useToolbarWixelProps();

  useInlineAiState: RicosEditorRef['useInlineAiState'] = invocationId =>
    this.tiptapAdapter.useInlineAiState(invocationId);

  useUndoState: RicosEditorRef['useUndoState'] = () => this.tiptapAdapter.useUndoState();

  getEditorCommands: RicosEditorRef['getEditorCommands'] = () => {
    return this.tiptapAdapter.getEditorCommands();
  };

  getEditorContainer: RicosEditorRef['getEditorContainer'] = () => {
    return this.tiptapAdapter.tiptapEditor.view.dom;
  };

  onSelectionUpdate = ({ selectedNodes, content, pmContent }: $TSFixMe) => {
    const { onAtomicBlockFocus, onChange, onInternalBusyChange } = this.props;
    this.isLastChangeEdit = false;

    invokeAtomicBlockFocus({
      selectedNodes,
      onAtomicBlockFocus,
    });

    if (onChange) {
      onChange(content, { source: 'selection' });
    }

    if (onInternalBusyChange) {
      onInternalBusyChange(pmContent);
    }
  };

  private getHtmlAttributes(): HtmlAttributes {
    return {
      autoCapitalize: this.props.htmlAttributes?.autoCapitalize || 'off',
      spellCheck: this.props.htmlAttributes?.spellCheck === false ? 'false' : 'true',
      autoComplete: this.props.htmlAttributes?.autoComplete || 'off',
      autoCorrect: this.props.htmlAttributes?.autoCorrect || 'off',
      tabIndex: this.props.htmlAttributes?.tabIndex || 0,
    };
  }

  onUpdate = ({ content, pmContent }: $TSFixMe) => {
    if (!this.firstEdit) {
      this.firstEdit = true;
      this.props.editor.publishFirstEdit();
    }
    this.isLastChangeEdit = true;
    this.props.onChange?.(content, { source: 'edit' });
    this.props.onInternalBusyChange?.(pmContent);
  };

  componentDidMount() {
    const htmlAttributes = this.getHtmlAttributes();

    this.setState({
      htmlAttributes,
    });

    this.props.editorEvents?.subscribe(EditorEvents.RICOS_PUBLISH, this.onPublish);

    addDevToolsClickListener(this.tiptapAdapter.tiptapEditor.view.dom, () =>
      this.setState({ debugInvokedWithMouse: true })
    );

    this.props.editor.publishLoaded();
  }

  componentWillUnmount() {
    this.props.editorEvents?.unsubscribe(EditorEvents.RICOS_PUBLISH, this.onPublish);
  }

  onPublish = async () => {
    const content = Promise.resolve(this.props.schema.getContent());
    const onPublish = this.props.helpers?.onPublish;
    publishBI(content, onPublish);
    this.props.editor.publishContentSaved();
    console.log('editor publish callback'); // oxlint-disable-line
    return {
      type: 'EDITOR_PUBLISH',
      data: await content,
    };
  };

  prePublish: RicosEditorRef['prePublish'] = async () => {
    // Dispatch plugin:publish for plugins that need to sync (e.g. polls)
    if (this.props.editorEvents) {
      await this.props.editorEvents.dispatch(EditorEvents.PUBLISH);
    }
    // Get content, fire BI, mark as saved
    const content = this.props.schema.getContent();
    const onPublish = this.props.helpers?.onPublish;
    publishBI(Promise.resolve(content), onPublish);
    this.props.editor.publishContentSaved();
    return content;
  };

  render() {
    const { ricosContext, onLoad, schema } = this.props;
    const { htmlAttributes } = this.state;
    const initialContent = schema.getTiptapContent();
    if (!initialContent) {
      return null;
    }
    return (
      <RicosTiptapEditor
        onLoad={onLoad}
        editor={this.tiptapAdapter.tiptapEditor}
        content={initialContent}
        t={ricosContext.t}
        onUpdate={this.onUpdate}
        onSelectionUpdate={this.onSelectionUpdate}
        htmlAttributes={htmlAttributes}
        editorStyleClasses={this.editorStyleClasses}
        preserveDomOnUnmount={this.props.preserveDomOnUnmount}
        devToolsElement={
          this.state.debugInvokedWithMouse ||
          shouldShowDebuggingInfo(ricosContext.debugMode?.includes('all')) ? (
            <React.Suspense>
              <RicosDevToolsLazy
                version={Version.currentVersion}
                mode="editor"
                contentState={schema.getContent()}
                ricosProps={this.props}
                autoOpen={this.state.debugInvokedWithMouse ?? false}
                editorView={this.tiptapAdapter.tiptapEditor.view}
              />
            </React.Suspense>
          ) : undefined
        }
      />
    );
  }
}

export const RicosEditorWithForwardRef = forwardRef<RicosEditorRef, RicosEditorWithOnBusyChange>(
  (props, ref) => (
    <RicosContextConsumer>
      {(ricosContext: GeneralContext) => (
        <SchemaContextConsumer>
          {(schema: RicosServices['schema']) => (
            <EditorContextConsumer>
              {(editor: RicosServices['editor']) => (
                <EditorEventsContext.Consumer>
                  {editorEvents => (
                    <RicosEditor
                      {...props}
                      ref={ref as ForwardedRef<RicosEditor>}
                      ricosContext={ricosContext}
                      editor={editor}
                      schema={schema}
                      editorEvents={editorEvents}
                    />
                  )}
                </EditorEventsContext.Consumer>
              )}
            </EditorContextConsumer>
          )}
        </SchemaContextConsumer>
      )}
    </RicosContextConsumer>
  )
);
